const raw = items[0].json;
const edges = raw?.data?.popularTitles?.edges || [];

function dedupeOffers(offers) {
  const groups = { FREE: [], FLATRATE: [], RENT: [], BUY: [] };
  const seen = new Set();
  for (const o of offers || []) {
    const type = o.monetizationType;
    if (!groups[type]) continue;
    const name = o.package?.clearName || '?';
    const key = type + '|' + name;
    if (seen.has(key)) continue;
    seen.add(key);
    groups[type].push({
      name,
      icon: o.package?.icon ? 'https://images.justwatch.com' + o.package.icon.replace('{profile}', 's100').replace('{format}', 'png') : '',
      url: o.standardWebURL || ''
    });
  }
  return groups;
}

const results = edges.map(e => {
  const n = e.node;
  return {
    id: n.id,
    type: n.objectType,
    title: n.content?.title || '',
    year: n.content?.originalReleaseYear || null,
    poster: n.content?.posterUrl ? 'https://images.justwatch.com' + n.content.posterUrl.replace('{profile}', 's276').replace('{format}', 'jpg') : '',
    justwatchUrl: n.content?.fullPath ? 'https://www.justwatch.com' + n.content.fullPath : '',
    offers: dedupeOffers(n.offers)
  };
});

return [{ json: { results } }];
